import java.util.*;
public class Main {
    static class Item {
        double w, v, r;
        Item(double w, double v) { this.w = w; this.v = v; this.r = v / w; }
    }
    public static void main(String[] args) {
        Locale.setDefault(Locale.US);
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        double cap = sc.nextDouble();
        Item[] items = new Item[n];
        for (int i = 0; i < n; i++) items[i] = new Item(sc.nextDouble(), sc.nextDouble());
        Arrays.sort(items, (a, b) -> Double.compare(b.r, a.r));
        double totalVal = 0.0;
        for (Item it : items) {
            if (cap >= it.w) { totalVal += it.v; cap -= it.w; }
            else if (cap > 0) { totalVal += it.r * cap; break; }
        }
        System.out.printf("%.2f\n", totalVal);
    }
}

