public class Main {
    static class Job {
        int d, p;
        Job(int d, int p) { this.d = d; this.p = p; }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        Job[] jobs = new Job[n];
        int maxD = 0;
        for (int i = 0; i < n; i++) {
            jobs[i] = new Job(sc.nextInt(), sc.nextInt());
            maxD = Math.max(maxD, jobs[i].d);
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(b.p, a.p));
        boolean[] slot = new boolean[maxD + 1];
        int count = 0, totalProfit = 0;
        for (Job j : jobs) {
            for (int s = j.d; s >= 1; s--) {
                if (!slot[s]) { slot[s] = true; count++; totalProfit += j.p; break; }
            }
        }
        System.out.println(count + " " + totalProfit);
    }
}

