import java.util.*;
public class Main {
    static class Job {
        int s, e, p;
        Job(int s, int e, int p) { this.s = s; this.e = e; this.p = p; }
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        Job[] jobs = new Job[n];
        for (int i = 0; i < n; i++) jobs[i] = new Job(sc.nextInt(), sc.nextInt(), sc.nextInt());
        Arrays.sort(jobs, (a, b) -> Integer.compare(a.e, b.e));
        long[] dp = new long[n];
        dp[0] = jobs[0].p;
        for (int i = 1; i < n; i++) {
            long incl = jobs[i].p;
            int l = 0, r = i - 1, latest = -1;
            while (l <= r) {
                int mid = (l + r) / 2;
                if (jobs[mid].e <= jobs[i].s) { latest = mid; l = mid + 1; }
                else r = mid - 1;
            }
            if (latest != -1) incl += dp[latest];
            dp[i] = Math.max(dp[i - 1], incl);
        }
        System.out.println(dp[n - 1]);
    }
}

